#include <vector>
#include <string>
#include <cstddef>
#include <omp.h>

struct Book {
    std::string title;
    int pages;
};

/* Return the index of the last Book item in the vector books where Book.pages is less than 100.
   Use OpenMP to search in parallel.
   Example:

   input: [{title="Green Eggs and Ham", pages=72}, {title="gulliver's travels", pages=362}, {title="Stories of Your Life", pages=54}, {title="Hamilton", pages=818}]
   output: 2
*/
size_t findLastShortBook(std::vector<Book> const& books) {
    if (books.empty()) {
        return books.size();
    }

    size_t last = books.size(); // sentinel for "not found"

    #pragma omp parallel for reduction(max:last)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(books.size()); ++i) {
        if (books[static_cast<size_t>(i)].pages < 100) {
            size_t idx = static_cast<size_t>(i);
            if (last == books.size() || idx > last) {
                last = idx;
            }
        }
    }

    return last;
}
