#include <vector>
#include <string>
#include <cstddef>
#include <limits>
#include <omp.h>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    const size_t n = books.size();
    if (n == 0) return n; // sentinel: not found

    // Use -1 as "not found" in a signed type so max-reduction is well-defined.
    long long lastIdx = -1;

    #pragma omp parallel for reduction(max:lastIdx)
    for (long long i = 0; i < static_cast<long long>(n); ++i) {
        if (books[static_cast<size_t>(i)].pages < 100) {
            if (i > lastIdx) lastIdx = i;
        }
    }

    return (lastIdx < 0) ? n : static_cast<size_t>(lastIdx);
}
